import base64
from security_client import SecurityClient
from security_models import EncryptionRequest, EncryptionResponse

class DecryptionRequest:
    def __init__(self, ciphertext_blob: str, encryption_context: dict = None):
        self.ciphertext_blob = ciphertext_blob
        self.encryption_context = encryption_context if encryption_context is not None else {}

class DecryptionResponse:
    def __init__(self, plaintext: str, key_id: str, arn: str):
        self.plaintext = plaintext
        self.key_id = key_id
        self.arn = arn

def decrypt_payload(request: DecryptionRequest) -> DecryptionResponse:
    client = SecurityClient()
    kms_client = client.get_kms_client()

    ciphertext_bytes = base64.b64decode(request.ciphertext_blob)

    response = kms_client.decrypt(
        CiphertextBlob=ciphertext_bytes,
        EncryptionContext=request.encryption_context
    )

    return DecryptionResponse(
        plaintext=response['Plaintext'].decode('utf-8'),
        key_id=response['KeyId'],
        arn=response['Arn']
    )

import base64
from security_client import SecurityClient

class SigningRequest:
    def __init__(self, message: str, key_id: str, signing_algorithm: str):
        self.message = message
        self.key_id = key_id
        self.signing_algorithm = signing_algorithm

class SigningResponse:
    def __init__(self, signature: bytes, key_id: str, signing_algorithm: str):
        self.signature = base64.b64encode(signature).decode('utf-8')
        self.key_id = key_id
        self.signing_algorithm = signing_algorithm

class VerificationRequest:
    def __init__(self, message: str, signature: str, key_id: str, signing_algorithm: str):
        self.message = message
        self.signature = signature
        self.key_id = key_id
        self.signing_algorithm = signing_algorithm

class VerificationResponse:
    def __init__(self, signature_valid: bool):
        self.signature_valid = signature_valid

def sign_message(request: SigningRequest) -> SigningResponse:
    client = SecurityClient()
    kms_client = client.get_kms_client()

    sign_response = kms_client.sign(
        KeyId=request.key_id,
        Message=request.message.encode('utf-8'),
        MessageType='RAW',
        SigningAlgorithm=request.signing_algorithm
    )

    return SigningResponse(
        signature=sign_response['Signature'],
        key_id=sign_response['KeyId'],
        signing_algorithm=request.signing_algorithm
    )

def verify_signature(request: VerificationRequest) -> VerificationResponse:
    client = SecurityClient()
    kms_client = client.get_kms_client()

    signature_bytes = base64.b64decode(request.signature)

    verify_response = kms_client.verify(
        KeyId=request.key_id,
        Message=request.message.encode('utf-8'),
        MessageType='RAW',
        Signature=signature_bytes,
        SigningAlgorithm=request.signing_algorithm
    )

    return VerificationResponse(
        signature_valid=verify_response['SignatureValid']
    )

from security_client import SecurityClient

class KeyUsageSummaryRequest:
    def __init__(self, key_id: str = None):
        self.key_id = key_id

class KeyUsageSummaryResponse:
    def __init__(self, key_summaries: list, key_details: dict = None):
        self.key_summaries = key_summaries
        self.key_details = key_details

def get_key_usage_summary(request: KeyUsageSummaryRequest) -> KeyUsageSummaryResponse:
    client = SecurityClient()
    kms_client = client.get_kms_client()

    key_summaries = []
    paginator = kms_client.get_paginator('list_keys')
    for page in paginator.paginate():
        for key in page['Keys']:
            key_summaries.append({
                'KeyId': key['KeyId'],
                'KeyArn': key['KeyArn']
            })

    key_details = None
    if request.key_id:
        try:
            describe_key_response = kms_client.describe_key(KeyId=request.key_id)
            key_details = describe_key_response['KeyMetadata']
        except Exception as e:
            key_details = {'error': str(e)}

    return KeyUsageSummaryResponse(
        key_summaries=key_summaries,
        key_details=key_details
    )

import os
import boto3

class PayloadSafetyRequest:
    def __init__(self, decrypted_text: str):
        self.decrypted_text = decrypted_text

class PayloadSafetyResponse:
    def __init__(self, unsafe_content_detected: bool, findings: list):
        self.unsafe_content_detected = unsafe_content_detected
        self.findings = findings

def check_payload_safety(request: PayloadSafetyRequest) -> PayloadSafetyResponse:
    region_name = os.environ.get("AWS_REGION", "us-east-1")
    comprehend_client = boto3.client("comprehend", region_name=region_name)

    findings = []
    unsafe_content_detected = False

    try:
        # Detect PII entities
        pii_response = comprehend_client.detect_pii_entities(Text=request.decrypted_text, LanguageCode='en')
        if pii_response['Entities']:
            unsafe_content_detected = True
            for entity in pii_response['Entities']:
                findings.append({
                    'Type': 'PII',
                    'Text': request.decrypted_text[entity['BeginOffset']:entity['EndOffset']],
                    'Category': entity['Type'],
                    'Score': entity['Score']
                })

        # You could add other detection like sentiment analysis or key phrases if relevant

    except Exception as e:
        findings.append({'Type': 'Error', 'Message': str(e)})
        # Depending on error, you might want to consider it unsafe or just log the error

    return PayloadSafetyResponse(
        unsafe_content_detected=unsafe_content_detected,
        findings=findings
    )

